<template><div v-if="customer" class="page-wrap pb-28 lg:pb-8"><NuxtLink to="/customers" class="text-sm font-bold text-slate-500">← Клиенты</NuxtLink><h1 class="mt-5 text-3xl font-black">{{ customer.company }}</h1><p class="mt-2 text-slate-500">{{ customer.name }} · {{ customer.email }} · {{ customer.phone }}</p><div class="mt-6 space-y-3"><RequestCard v-for="request in requests" :key="request.id" :request="request" /></div></div></template>
<script setup lang="ts">import type { CustomerSummary, PaginatedResponse, ServiceRequest } from '#shared/types/domain'; definePageMeta({ middleware: 'staff' }); const id = useRoute().params.id as string; const { data: customers } = await useFetch<CustomerSummary[]>('/api/customers'); const customer = computed(() => customers.value?.find(item => item.id === id)); if (!customer.value) throw createError({ statusCode: 404, statusMessage: 'Клиент не найден' }); const { data } = await useFetch<PaginatedResponse<ServiceRequest>>('/api/requests', { query: { customerId: id, pageSize: 50 } }); const requests = computed(() => data.value?.data ?? []); useSeoMeta({ title: customer.value.company })</script>
